import{_ as o,o as t,c as d,a2 as c}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"CLI 명령어","description":"","frontmatter":{},"headers":[],"relativePath":"ko/cli/overview.md","filePath":"ko/cli/overview.md","lastUpdated":1784903584000}'),r={name:"ko/cli/overview.md"};function a(l,e,i,n,s,h){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="cli-명령어" tabindex="-1">CLI 명령어 <a class="header-anchor" href="#cli-명령어" aria-label="Permalink to &quot;CLI 명령어&quot;">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p><code>swag2mcp</code> CLI는 워크스페이스 초기화 및 API 명세 관리부터 LLM 통합을 위한 MCP 서버 시작까지 모든 작업의 단일 진입점입니다. OpenAPI/Swagger/Postman 명세 작업의 전체 라이프사이클을 다루는 <strong>13개의 명령어</strong>를 제공합니다.</p><h3 id="cli가-해결하는-문제" tabindex="-1">CLI가 해결하는 문제 <a class="header-anchor" href="#cli가-해결하는-문제" aria-label="Permalink to &quot;CLI가 해결하는 문제&quot;">​</a></h3><ul><li><strong>워크스페이스 라이프사이클</strong> — 생성(<code>init</code>), 검사(<code>info</code>, <code>ls</code>), 정리(<code>clean</code>), 업데이트(<code>update</code>), 제거(<code>delete</code>)</li><li><strong>Spec 및 Collection 관리</strong> — 추가(<code>add</code>), 나열(<code>ls</code>), 삭제(<code>delete</code>)</li><li><strong>실행 모드</strong> — LLM 도구 접근을 위한 MCP 서버 시작(<code>mcp</code>) 또는 대화형 TUI 탐색기 실행(<code>run</code>)</li><li><strong>진단</strong> — 설정 검증(<code>validate</code>), 버전 표시(<code>version</code>), 런타임 정보 표시(<code>info</code>)</li><li><strong>백업 및 복원</strong> — ZIP을 통한 전체 워크스페이스 왕복(<code>export</code>, <code>import</code>)</li></ul><h3 id="주요-세부-사항" tabindex="-1">주요 세부 사항 <a class="header-anchor" href="#주요-세부-사항" aria-label="Permalink to &quot;주요 세부 사항&quot;">​</a></h3><ul><li><strong>경로 해결</strong> — <code>[path]</code>를 받는 명령어는 <strong>워크스페이스 디렉토리</strong>(파일 경로가 아님)를 기대합니다. 해결 순서: 명시적 <code>[path]</code> → 현재 디렉토리(<code>./</code>) → <code>~/.swag2mcp/</code>. CLI가 자동으로 <code>swag2mcp.yaml</code>을 추가합니다. 서비스로 실행하거나 IDE 설정에서 잘못된 워크스페이스 로드를 방지하기 위해 항상 명시적 경로를 전달하세요.</li><li><strong>Spec vs Collection</strong> — <strong>spec</strong>은 논리적 API 서비스(예: &quot;Open-Meteo API&quot;)를 나타내고, <strong>collection</strong>은 하나의 OpenAPI/Swagger/Postman 파일입니다. 하나의 spec은 여러 collection을 가질 수 있습니다.</li><li><strong><code>--version</code></strong> 은 플래그(<code>swag2mcp --version</code>)와 하위 명령어(<code>swag2mcp version</code>) 모두로 지원됩니다.</li><li><strong><code>add spec</code> / <code>add collection</code></strong> 은 <code>--yaml</code>(인라인 문자열 또는 stdin용 <code>-</code>)을 통해 YAML 입력을 받습니다. 파일 또는 heredoc에서 파이핑하면 특수 문자로 인한 셸 따옴표 문제를 피할 수 있습니다.</li><li><strong><code>delete</code></strong> 는 TTY(대화형 터미널)가 필요합니다. <code>--force</code> 또는 <code>--yes</code> 플래그가 없습니다 — 항상 선택 및 확인을 위한 프롬프트를 표시합니다.</li><li><strong><code>mcp</code></strong> 는 LLM 통합을 위한 기본 명령어입니다. 세 가지 전송 방식을 지원합니다: <code>stdio</code>(기본값), <code>sse</code>, <code>streamable-http</code>. <code>--disable-llm-auth</code> 플래그(기본값: <code>true</code>)는 MCP 도구 목록에서 <code>auth</code> 도구를 제거하여 LLM이 토큰을 보거나 요청하지 못하게 합니다. 인증은 여전히 작동합니다 — 토큰은 LLM을 통하지 않고 표준 설정 메커니즘을 통해 획득됩니다. 이 모드는 <strong>프로덕션</strong>에 권장됩니다(LLM이 자격 증명에 접근할 수 없음). <strong>디버깅</strong> 또는 단기 토큰 사용 시 <code>--disable-llm-auth=false</code>로 설정하여 LLM이 <code>auth</code> 도구를 통해 새 토큰을 요청하도록 허용하세요.</li><li><strong><code>validate</code></strong> 는 YAML 구문, 설정 구조, 명세 파일 존재 여부, URL 접근성, 명세 형식(OpenAPI/Swagger/Postman), 인증 설정, HTTP 클라이언트 정확성을 확인합니다. 인증 엔드포인트나 API 엔드포인트 가용성은 <strong>테스트하지 않습니다</strong>.</li><li><strong><code>export</code> / <code>import</code></strong> 는 전체 워크스페이스 왕복을 제공합니다 — 설정 파일, 명세 파일, 캐시, 인증 스크립트가 모두 ZIP 아카이브에 포함됩니다.</li><li><strong><code>clean</code></strong> 은 <code>cache/</code>와 <code>responses/</code> 디렉토리를 제거하지만 <code>specs/</code>와 <code>auth_scripts/</code>는 보존합니다. 오래된 응답(48시간 초과)은 <code>mcp</code> 시작 시 자동으로 정리됩니다.</li></ul><h2 id="명령어" tabindex="-1">명령어 <a class="header-anchor" href="#명령어" aria-label="Permalink to &quot;명령어&quot;">​</a></h2><table tabindex="0"><thead><tr><th>명령어</th><th>설명</th></tr></thead><tbody><tr><td><a href="/cli/init"><code>init</code></a></td><td>기본 설정으로 워크스페이스 디렉토리 초기화</td></tr><tr><td><a href="/cli/add"><code>add</code></a></td><td>설정에 spec 또는 collection 추가</td></tr><tr><td><a href="/cli/delete"><code>delete</code></a></td><td>대화형으로 spec 또는 collection 삭제</td></tr><tr><td><a href="/cli/ls"><code>ls</code></a></td><td>모든 spec과 해당 collection 나열</td></tr><tr><td><a href="/cli/run"><code>run</code></a></td><td>대화형 TUI API 탐색기 실행</td></tr><tr><td><a href="/cli/validate"><code>validate</code></a></td><td>설정 및 명세 파일 검증</td></tr><tr><td><a href="/cli/clean"><code>clean</code></a></td><td>캐시된 명세와 호출 응답 지우기</td></tr><tr><td><a href="/cli/update"><code>update</code></a></td><td>모든 spec 재검증, 재캐싱, 재인덱싱</td></tr><tr><td><a href="/cli/mcp"><code>mcp</code></a></td><td>LLM 도구 접근을 위한 MCP 서버 시작</td></tr><tr><td><a href="/cli/version"><code>version</code></a></td><td>swag2mcp 버전 출력</td></tr><tr><td><a href="/cli/info"><code>info</code></a></td><td>상세 설정 및 런타임 정보 표시</td></tr><tr><td><a href="/cli/import"><code>import</code></a></td><td>명세 파일 가져오기 또는 ZIP에서 워크스페이스 복원</td></tr><tr><td><a href="/cli/export"><code>export</code></a></td><td>워크스페이스를 이식 가능한 ZIP 백업으로 내보내기</td></tr></tbody></table><h2 id="전역-플래그" tabindex="-1">전역 플래그 <a class="header-anchor" href="#전역-플래그" aria-label="Permalink to &quot;전역 플래그&quot;">​</a></h2><table tabindex="0"><thead><tr><th>플래그</th><th>설명</th></tr></thead><tbody><tr><td><code>--version</code></td><td>버전 표시 (<code>version</code> 하위 명령어와 동일)</td></tr><tr><td><code>--help</code></td><td>모든 명령어에 대한 도움말 표시</td></tr></tbody></table>',11)])])}const m=o(r,[["render",a]]);export{g as __pageData,m as default};
